return {["scripts/actions/abilities/spirit_jump.lua"]={["Path"]="scripts/actions/abilities/spirit_jump.lua",["SHA256"]="2b293564ec37bbb4711e52203f9f2e10015282b5c8d4503755d166d94e3ac72c",["Text"]="-----------------------------------\n-- Ability: Spirit Jump\n-- Description: Delivers a short jumping attack on a targeted enemy which suppresses enmity. Effect enhanced when wyvern is present.\n-- Obtained: DRG Level 77\n-- Recast Time: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useSpiritJump(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spirit_link.lua"]={["Path"]="scripts/actions/abilities/spirit_link.lua",["SHA256"]="a7ba99e1e1df06e98d6792f9a35bf552c346f8ced97700b4b2a631613a9fd294",["Text"]="-----------------------------------\n-- Ability: Spirit Link\n-- Sacrifices own HP to heal Wyvern's HP.\n-- Obtained: Dragoon Level 25\n-- Recast Time: 1:30\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dragoon.abilityCheckSpiritLink(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useSpiritLink(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spirit_surge.lua"]={["Path"]="scripts/actions/abilities/spirit_surge.lua",["SHA256"]="3a2f3b5d271409a50a838d366ff3dcfd6ce86e3c1e11ace56ec212ee54a48131",["Text"]="-----------------------------------\n-- Ability: Spirit Surge\n-- Adds your wyvern's strength to your own.\n-- Obtained: Dragoon Level 1\n-- Recast Time: 1:00:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- The wyvern must be present in order to use Spirit Surge\n    return xi.job_utils.dragoon.abilityCheckRequiresPet(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dragoon.useSpiritSurge(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spontaneity.lua"]={["Path"]="scripts/actions/abilities/spontaneity.lua",["SHA256"]="d6a3c4d59099fc3036ed0357302f6ad1dca3fe00fa97debd42ce787d583a8bbb",["Text"]="-----------------------------------\n-- Ability: Spontaneity\n-- Reduces casting time for the next magic spell the target casts.\n-- Obtained: Red Mage Level 95\n-- Recast Time: 10:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.red_mage.useSpontaneity(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/spur.lua"]={["Path"]="scripts/actions/abilities/spur.lua",["SHA256"]="314c83be5e9840402ab17d148d2d1762701b2e16da65931b0199e5bf19242e9d",["Text"]="-----------------------------------\n-- Ability: Spur\n-- Grants \"Store TP\" effect to pets.\n-- Obtained: Beastmaster Level 83\n-- Recast Time: 3 Minutes\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- same requirements as snarl: pet exists and is attacking a target\n    return xi.job_utils.beastmaster.checkSnarl(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useSpur(player)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/stay.lua"]={["Path"]="scripts/actions/abilities/stay.lua",["SHA256"]="e9968361fe50df05f6047ab351c52b00ae709472653f19201253736b14ff22eb",["Text"]="-----------------------------------\n-- Ability: Stay\n-- Commands the Pet to stay in one place.\n-- Obtained: Beastmaster Level 15\n-- Recast Time: 5 seconds\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkPetCommand(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useStay(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/steady_wing.lua"]={["Path"]="scripts/actions/abilities/steady_wing.lua",["SHA256"]="a0c0a7de4d6c0608385e876e2222d98037cd755ddcf43b64ab7625f3a0a4672b",["Text"]="-----------------------------------\n-- Ability: Steady Wing\n-- Creates a barrier that temporarily absorbs a certain amount of damage dealt to your wyvern.\n-- Obtained: Dragoon Level 95\n-- Recast Time: 05:00\n-- Duration:    03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    -- You can't actually use Steady Wing on retail unless your wyvern is up\n    -- This is on the pet menu, but just in case...\n    return xi.job_utils.dragoon.abilityCheckRequiresPet(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dragoon.useSteadyWing(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/steal.lua"]={["Path"]="scripts/actions/abilities/steal.lua",["SHA256"]="1b1e6df440baf900f149668db4e40781a61335124e849d516790ce3825af76c1",["Text"]="-----------------------------------\n-- Ability: Steal\n-- Steal items from enemy.\n-- Obtained: Thief Level 5\n-- Recast Time: 5:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.thief.checkSteal(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.thief.useSteal(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/stealth_shot.lua"]={["Path"]="scripts/actions/abilities/stealth_shot.lua",["SHA256"]="9097ebf09b4882a0e33e9dc229c77938798d5344701d4749ba52fd2bf16aa581",["Text"]="-----------------------------------\n-- Ability: Stealth Shot\n-- Your next attack will generate less enmity.\n-- Obtained: Ranger Level 75\n-- Recast Time: 5:00\n-- Duration: 1:00\n-- Target: Self Only\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkStealthShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useStealthShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/striking_flourish.lua"]={["Path"]="scripts/actions/abilities/striking_flourish.lua",["SHA256"]="b52ad06e2d922bac7fa09a3241c28d70d2ee13d8387f05bc896a48a42c295eaf",["Text"]="-----------------------------------\n-- Ability: Striking Flourish\n-- Description: Allows you to deliver a twofold attack. Requires at least two finishing moves.\n-- Obtained: DNC Level 89\n-- Recast Time: 00:00:30 (Flourishes III)\n-- Duration: 00:01:00\n-- Cost: 2 Finishing Move charges\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_2) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_3) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_4) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_5)\n    then\n        return 0, 0\n    end\n\n    return xi.msg.basic.NO_FINISHINGMOVES, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FINISHING_MOVE_2) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_2)\n        player:addStatusEffect(xi.effect.STRIKING_FLOURISH, { power = 2, duration = 60, origin = player })\n    elseif player:hasStatusEffect(xi.effect.FINISHING_MOVE_3) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_3)\n        player:addStatusEffect(xi.effect.FINISHING_MOVE_1, { power = 1, duration = 7200, origin = player })\n        player:addStatusEffect(xi.effect.STRIKING_FLOURISH, { power = 3, duration = 60, origin = player })\n    elseif player:hasStatusEffect(xi.effect.FINISHING_MOVE_4) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_4)\n        player:addStatusEffect(xi.effect.FINISHING_MOVE_2, { power = 1, duration = 7200, origin = player })\n        player:addStatusEffect(xi.effect.STRIKING_FLOURISH, { power = 3, duration = 60, origin = player })\n    elseif player:hasStatusEffect(xi.effect.FINISHING_MOVE_5) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_5)\n        player:addStatusEffect(xi.effect.FINISHING_MOVE_3, { power = 1, duration = 7200, origin = player })\n        player:addStatusEffect(xi.effect.STRIKING_FLOURISH, { power = 3, duration = 60, origin = player })\n    end\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/stutter_step.lua"]={["Path"]="scripts/actions/abilities/stutter_step.lua",["SHA256"]="af99c2f983e88c02a41706af13929a96bd45cebfdbd55446a8c3e6429a55b7cd",["Text"]="-----------------------------------\n-- Ability: Stutter Step\n-- Applies Weakened Daze. Lowers the targets magic resistance. If successful, you will earn two Finishing Moves.\n-- Obtained: Dancer Level 40\n-- TP Required: 10%\n-- Recast Time: 00:05\n-- Duration: First Step lasts 1 minute, each following Step extends its current duration by 30 seconds.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkStepAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useStepAbility(player, target, ability, action, xi.effect.WEAKENED_DAZE_1)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/stymie.lua"]={["Path"]="scripts/actions/abilities/stymie.lua",["SHA256"]="e803303fbb63313404af4141080c04318d2df0d5e9abccc47fbdeb6b894d0380",["Text"]="-----------------------------------\n-- Ability: Stymie\n-- Greatly increases the accuracy of the next enfeebling magic spell.\n-- Obtained: Red Mage Level 96\n-- Recast Time: 1:00:00\n-- Duration: Stymie fades after either sixty seconds passes or a spell lands, but it does not fade if the spell is resisted.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.red_mage.checkStymie(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.red_mage.useStymie(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/sublimation.lua"]={["Path"]="scripts/actions/abilities/sublimation.lua",["SHA256"]="808e197ca92d0bf332d44b44a26f19fd103d38972bfcddb943f217f91596df05",["Text"]="-----------------------------------\n-- Ability: Sublimation\n-- Gradually creates a storage of MP while reducing your HP. The effect ends once an MP limit is reached, or your HP has gone too low. The stored MP is then transferred to your MP pool by using the ability a second time.\n-- Obtained: Scholar Level 35\n-- Recast Time: 30 seconds after the ability is reactivated\n-- Duration (Charging): Until MP stored is 25% of Max HP or until HP = 50%\n-- Duration (Charged): 2 hours\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local mp        = 0\n    local maxMP     = player:getMaxMP()\n    local currentMP = player:getMP()\n\n    if player:hasStatusEffect(xi.effect.SUBLIMATION_COMPLETE) then\n        mp = player:getStatusEffect(xi.effect.SUBLIMATION_COMPLETE):getPower()\n\n        if mp + currentMP > maxMP then\n            mp = maxMP - currentMP\n        end\n\n        player:addMP(mp)\n        player:delStatusEffectSilent(xi.effect.SUBLIMATION_COMPLETE)\n        ability:setMsg(xi.msg.basic.JA_RECOVERS_MP)\n    elseif player:hasStatusEffect(xi.effect.SUBLIMATION_ACTIVATED) then\n        mp = player:getStatusEffect(xi.effect.SUBLIMATION_ACTIVATED):getPower()\n\n        if mp + currentMP > maxMP then\n            mp = maxMP - currentMP\n        end\n\n        player:addMP(mp)\n        player:delStatusEffectSilent(xi.effect.SUBLIMATION_ACTIVATED)\n        ability:setMsg(xi.msg.basic.JA_RECOVERS_MP)\n    else\n        local refreshTier = player:hasStatusEffect(xi.effect.REFRESH) and player:getStatusEffect(xi.effect.REFRESH):getTier() or 0\n        if refreshTier < 3 then\n            player:delStatusEffect(xi.effect.REFRESH)\n            player:addStatusEffect(xi.effect.SUBLIMATION_ACTIVATED, { duration = 7200, origin = player, tick = 3 })\n        else\n            ability:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        end\n    end\n\n    return mp\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/subtle_sorcery.lua"]={["Path"]="scripts/actions/abilities/subtle_sorcery.lua",["SHA256"]="3ca6b762f35f50205c5b3a8052b75b8c0eda90cf3b853bf793a14e628efd5377",["Text"]="-----------------------------------\n-- Ability: Subtle Sorcery\n-- Description: Reduces the amount of enmity generated from magic spells and increases magic accuracy.\n-- Obtained: BLM Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.black_mage.checkSubtleSorcery(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useSubtleSorcery(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/sulpor.lua"]={["Path"]="scripts/actions/abilities/sulpor.lua",["SHA256"]="a5ea59fff3cfeaf6f85713c09a3eb6a931d8ab27205b7e081e87380a3ab6380f",["Text"]="-----------------------------------\n-- Ability: Sulpor\n-- Increases resistance against earth and deals thunder damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.SULPOR)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/super_jump.lua"]={["Path"]="scripts/actions/abilities/super_jump.lua",["SHA256"]="e9cc3a728eba4118d0ae2314ea454e5a820dfa5b248b46707c81050043849725",["Text"]="-----------------------------------\n-- Ability: Super Jump\n-- Performs a super jump.\n-- Obtained: Dragoon Level 50\n-- Recast Time: 3:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.dragoon.useSuperJump(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/swipe.lua"]={["Path"]="scripts/actions/abilities/swipe.lua",["SHA256"]="f32b21e2afcb3fb58736947ed09c9963b985fa90ac94a80787f3e085a242ec8e",["Text"]="-----------------------------------\n-- Ability: Swipe\n-- Expends a single rune to deal damage to a target.\n-- Obtained: Rune Fencer Level 25\n-- Recast Time: 1:30\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:getAnimation() ~= 1 then\n        return xi.msg.basic.REQUIRES_COMBAT, 0\n    end\n\n    return xi.job_utils.rune_fencer.checkHaveRunes(player)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useSwipeLunge(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/swordplay.lua"]={["Path"]="scripts/actions/abilities/swordplay.lua",["SHA256"]="3115c9ffc783eaba6fde94b3bfead0c3da2fdb374903209a62244573c7f3913d",["Text"]="-----------------------------------\n-- Ability: Swordplay\n-- Increases accuracy and evasion until you take severe damage.\n-- Obtained: Rune Fencer level 20\n-- Recast Time: 5:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.rune_fencer.useSwordplay(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tabula_rasa.lua"]={["Path"]="scripts/actions/abilities/tabula_rasa.lua",["SHA256"]="3fcc9b04c699f8231340b7090f10eb77fd36fb3eb7b97d22727c45c72e7f2f32",["Text"]="-----------------------------------\n-- Ability: Tabula Rasa\n-- Optimizes both white and black magic capabilities while allowing charge-free stratagem use.\n-- Obtained: Scholar Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local regenbonus = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        regenbonus = 3 * math.floor((player:getMainLvl() - 10) / 10)\n    end\n\n    local helixbonus = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        helixbonus = math.floor(player:getMainLvl() / 4)\n    end\n\n    local jpValue = player:getJobPointLevel(xi.jp.TABULA_RASA_EFFECT)\n\n    if jpValue > 0 then\n        player:addMP(player:getMaxMP() * 0.02 * jpValue)\n    end\n\n    player:resetRecast(xi.recast.ABILITY, 228)\n    player:resetRecast(xi.recast.ABILITY, 231)\n    player:resetRecast(xi.recast.ABILITY, 232)\n    player:addStatusEffect(xi.effect.TABULA_RASA, { power = math.floor(helixbonus * 1.5), duration = 180, origin = player, subPower = math.floor(regenbonus * 1.5) })\n\n    return xi.effect.TABULA_RASA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tactical_switch.lua"]={["Path"]="scripts/actions/abilities/tactical_switch.lua",["SHA256"]="b03a15058723c2c237b263b542ec8d1796c7e07c4ae0707dc894343ff768cae5",["Text"]="-----------------------------------\n-- Ability: Tactical Switch\n-- Description: Swaps TP of master and automaton.\n-- Obtained: PUP Level 79\n-- Recast Time: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckTacticalSwitch(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.puppetmaster.onAbilityUseTacticalSwitch(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tacticians_roll.lua"]={["Path"]="scripts/actions/abilities/tacticians_roll.lua",["SHA256"]="5148af8e98ac3774ec471e0de91fed26484d463d44e65b553a4252eac14bce12",["Text"]="-----------------------------------\n-- Ability: Tacticians's Roll\n-- Grants a Regain effect to party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 5\n-- Unlucky Number: 8\n-- Level: 86\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    | Regain\n-- --------    -------\n-- 1           |+10\n-- 2           |+10\n-- 3           |+10\n-- 4           |+10\n-- 5           |+30\n-- 6           |+10\n-- 7           |+10\n-- 8           |+0\n-- 9           |+20\n-- 10          |+20\n-- 11          |+40\n-- Bust        |-10\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tame.lua"]={["Path"]="scripts/actions/abilities/tame.lua",["SHA256"]="a28857a496b051dac2feb6966f3df9744727bcc8509c67fa971b7c5205815cc4",["Text"]="-----------------------------------\n-- Ability: Tame\n-- Makes target docile and more susceptible to charm.\n-- Obtained: Beastmaster Level 30\n-- Recast Time: 10:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkTame(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useTame(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tellus.lua"]={["Path"]="scripts/actions/abilities/tellus.lua",["SHA256"]="b6cb9beb5ef46537a9146a48a59a503c47d6b3486ecab73fa4593ec8a24c791d",["Text"]="-----------------------------------\n-- Ability: Tellus\n-- Increases resistance against thunder and deals earth damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.TELLUS)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tenebrae.lua"]={["Path"]="scripts/actions/abilities/tenebrae.lua",["SHA256"]="e772c900931cdf051574a1b7a24b31b0aca0c46831e0d02c0aa04a3450c3e0a4",["Text"]="-----------------------------------\n-- Ability: Tenebrae\n-- Increases resistance against light and deals dark damage.\n-- Obtained: Rune Fencer Level 5\n-- Recast Time: 0:05\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.rune_fencer.useRuneEnchantment(player, target, ability, xi.effect.TENEBRAE)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tenuto.lua"]={["Path"]="scripts/actions/abilities/tenuto.lua",["SHA256"]="782c7e782c787cacba647dcff0d120cb5fa60cd12e219746c05ea0e63c17e4d2",["Text"]="-----------------------------------\n-- Ability: Tenuto\n-- If the next song you cast affects yourself, it will not subsequently be overwritten by other songs.\n-- Obtained: Bard Level 83\n-- Recast Time: 0:15\n-- Duration: 1:00, or until next song is cast.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.bard.useTenuto(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ternary_flourish.lua"]={["Path"]="scripts/actions/abilities/ternary_flourish.lua",["SHA256"]="4a5eca7d962f130693ee116a30049e302969181ac0b3e96d4457feb64092873a",["Text"]="-----------------------------------\n-- Ability: Ternary Flourish\n-- Description: Allows you to deliver a threefold attack. Requires at least three finishing moves.\n-- Obtained: DNC Level 93\n-- Recast Time: 00:00:45 (Flourishes III)\n-- Duration: 00:01:00\n-- Cost: 3 Finishing Move charges\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_3) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_4) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_5)\n    then\n        return 0, 0\n    end\n\n    return xi.msg.basic.NO_FINISHINGMOVES, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FINISHING_MOVE_3) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_3)\n        player:addStatusEffect(xi.effect.TERNARY_FLOURISH, { power = 3, duration = 60, origin = player })\n    elseif player:hasStatusEffect(xi.effect.FINISHING_MOVE_4) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_4)\n        player:addStatusEffect(xi.effect.FINISHING_MOVE_1, { power = 1, duration = 7200, origin = player })\n        player:addStatusEffect(xi.effect.TERNARY_FLOURISH, { power = 3, duration = 60, origin = player })\n    elseif player:hasStatusEffect(xi.effect.FINISHING_MOVE_5) then\n        player:delStatusEffect(xi.effect.FINISHING_MOVE_5)\n        player:addStatusEffect(xi.effect.FINISHING_MOVE_2, { power = 1, duration = 7200, origin = player })\n        player:addStatusEffect(xi.effect.TERNARY_FLOURISH, { power = 3, duration = 60, origin = player })\n    end\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/theurgic_focus.lua"]={["Path"]="scripts/actions/abilities/theurgic_focus.lua",["SHA256"]="f5b3d8c04655f0e69079ce119ccc47d99ba2121aac0d0d4ef6755dc1782e818c",["Text"]="-----------------------------------\n-- Ability: Theurgic Focus\n-- Increases the power of your next applicable elemental magic spell. Casting range and area of effect are reduced by half.\n-- Obtained: Geomancer Level 80\n-- Recast Time: 00:05:00\n-- Duration: 00:01:00 or next elemental magic spell.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnTheurgicFocusCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.geomancer.theurgicFocus(player, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/third_eye.lua"]={["Path"]="scripts/actions/abilities/third_eye.lua",["SHA256"]="a0d7b4b7117f8ec226c6f8ba05d06c5cc32b748eec6e4ff73992f75ac56ee7f7",["Text"]="-----------------------------------\n-- Ability: Third Eye\n-- Anticipates and dodges the next attack directed at you.\n-- Obtained: Samurai Level 15\n-- Recast Time: 1:00\n-- Duration: 0:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.samurai.checkThirdEye(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.samurai.useThirdEye(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/thunder_maneuver.lua"]={["Path"]="scripts/actions/abilities/thunder_maneuver.lua",["SHA256"]="98c140e2bc8540ffd728f08e1f5d8cc39087da7225e601a6eee359c29ebd3dc3",["Text"]="-----------------------------------\n-- Ability: Thunder Maneuver\n-- Enhances the effect of thunder attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/thunder_shot.lua"]={["Path"]="scripts/actions/abilities/thunder_shot.lua",["SHA256"]="c3c77942f7353dd32a52299771c10a6a70b4a2e14e1e6d2b65ab44e5c0abff96",["Text"]="-----------------------------------\n-- Ability: Thunder Shot\n-- Consumes a Thunder Card to enhance lightning-based debuffs. Deals lightning-based magic damage\n-- Shock Effect: Enhanced DoT and MND-\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/tomahawk.lua"]={["Path"]="scripts/actions/abilities/tomahawk.lua",["SHA256"]="9016f9496293429c89d0bfd033c4a58c5bcd2a3f65ae70fa7d6785ff6ed478fb",["Text"]="-----------------------------------\n-- Ability: Tomahawk\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.warrior.checkTomahawk(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.warrior.useTomahawk(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/trance.lua"]={["Path"]="scripts/actions/abilities/trance.lua",["SHA256"]="109ff7a6dc55fcd60d5cc3ed30937a81a0aff7870d947690511a63f4a75b25ee",["Text"]="-----------------------------------\n-- Ability: Trance\n-- While in effect, lowers TP cost of dances and steps to 0.\n-- Obtained: Dancer Level 1\n-- Recast Time: 1:00:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.TRANCE, { power = 1, duration = 60, origin = player })\n    player:addTP(100 * player:getJobPointLevel(xi.jp.TRANCE_EFFECT))\nend\n\nreturn abilityObject\n"}};
